function setView(view){const p=ensure();state.view=view;p.querySelector('.fb-msg-inbox-view').style.display=view==='inbox'?'block':'none';p.querySelector('.fb-msg-global-search').classList.toggle('show',view==='search');p.querySelector('.fb-msg-contact-head').classList.toggle('show',view==='contacts');p.querySelector('.fb-msg-chat').classList.toggle('is-active',view==='chat');if(view!=='chat'){state.reply=null;state.editing=null;renderReply();}if(view==='inbox')renderInbox();}
async function openMessenger(user){const p=ensure();state.open=true;p.classList.add('is-open');document.body.style.overflow='hidden';connect();if(user&&user.id){await openDirect(user.id);return;}setView('inbox');const cached=await cacheGet('inbox');if(cached?.value?.length&&!state.inbox.length){state.inbox=cached.value;renderInbox();}refreshInbox();}
function closeMessenger(){state.open=false;ensure().classList.remove('is-open');document.body.style.overflow='';}
window.__facebookOpenMessenger=()=>openMessenger();
window.__facebookReturnToMessengerConversation=()=>{const p=ensure();state.open=true;p.classList.add('is-open');document.body.style.overflow='hidden';connect();if(state.active){setView('chat');renderChatHeader();renderMessages(true);markRead();}else{setView('inbox');refreshInbox();}};
window.addEventListener('facebookmessagerequest',e=>{const u=e.detail?.user;if(u?.id)openMessenger(u);else openMessenger();});
