async function sendFile(file,kindOverride){if(!state.active||!file)return;if(file.size>12*1024*1024)return toast('File must be 12 MB or smaller.');const reply=state.reply;state.reply=null;renderReply();const kind=kindOverride||(file.type.startsWith('image/')?'image':file.type.startsWith('video/')?'video':file.type.startsWith('audio/')?'audio':'file');const local=URL.createObjectURL(file);const temp=optimistic('',kind,{id:'local',name:file.name||'attachment',mimeType:file.type,size:file.size,url:local});try{const r=await fetch(`${API}/conversations/${state.active.id}/attachment`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name||'attachment'),'X-File-Type':file.type||'application/octet-stream','X-Client-Id':temp.clientId,'X-Reply-To-Id':reply?.id||''},body:file});let d={};try{d=await r.json()}catch(_error){}if(!r.ok)throw new Error(d.error||'Could not send attachment.');URL.revokeObjectURL(local);replaceTemp(temp.clientId,d.message);}catch(e){temp.pending=false;renderMessages(false);toast(e.message);}}
function messageActions(m,line){const body=ensure().querySelector('[data-msg-sheet-body]');const mine=String(m.senderId)===String(state.selfId),editable=mine&&m.type==='text'&&Boolean(String(m.body||'').trim());body.innerHTML=`<div class="fb-msg-reaction-row">${['❤️','👍','😂','😮','😢','😡'].map(e=>`<button data-react="${e}">${e}</button>`).join('')}</div><div class="fb-msg-sheet-actions"><button data-act="reply">↩ Reply</button>${editable?'<button data-act="edit">✎ Edit</button>':''}${mine&&!m.deleted?'<button data-act="unsend">🗑 Unsend</button>':''}<button data-act="delete-me">Hide for me</button></div>`;showSheet();body.querySelectorAll('[data-react]').forEach(b=>b.onclick=async()=>{hideSheet();window.__facebookMessengerHoldMessagePosition?.(line);try{const current=(m.reactions||[]).find(r=>String(r.userId)===String(state.selfId));const emoji=current?.emoji===b.dataset.react?'':b.dataset.react;const d=await api(API+'/messages/'+m.id+'/reaction',{method:'POST',body:JSON.stringify({emoji})});replaceMessage(d.message);}catch(e){toast(e.message);}});body.querySelectorAll('[data-act]').forEach(b=>b.onclick=async()=>{const a=b.dataset.act;hideSheet();if(a==='reply'){state.reply=m;renderReply();ensure().querySelector('[data-msg-input]').focus();}else if(a==='edit'){state.editing=m;renderReply();const input=ensure().querySelector('[data-msg-input]');input.value=m.body||'';input.focus();}else if(a==='unsend'){try{const d=await api(API+'/messages/'+m.id+'?scope=everyone',{method:'DELETE'});if(d.message)replaceMessage(d.message);}catch(e){toast(e.message);}}else if(a==='delete-me'){try{await api(API+'/messages/'+m.id+'?scope=me',{method:'DELETE'});state.messages=state.messages.filter(x=>String(x.id)!==String(m.id));renderMessages(false);}catch(e){toast(e.message);}}});}
function showSheet(){ensure().querySelector('[data-msg-sheet]').classList.add('show');}function hideSheet(){ensure().querySelector('[data-msg-sheet]').classList.remove('show');}
function infoSheet(){const c=state.active;if(!c)return;const body=ensure().querySelector('[data-msg-sheet-body]');body.innerHTML=`<h3 style="margin:4px 5px 12px">${esc(c.name)}</h3><button class="fb-msg-setting" style="width:100%;margin:4px 0" data-setting="pinned">${c.pinned?'Unpin':'Pin'} conversation</button><button class="fb-msg-setting" style="width:100%;margin:4px 0" data-setting="muted">${c.mutedUntil?'Unmute':'Mute for 8 hours'}</button><button class="fb-msg-setting" style="width:100%;margin:4px 0" data-setting="archived">Archive conversation</button><button class="fb-msg-setting" style="width:100%;margin:4px 0" data-setting="search">Search in conversation</button>`;showSheet();body.querySelectorAll('[data-setting]').forEach(b=>b.onclick=async()=>{const k=b.dataset.setting;if(k==='search'){hideSheet();const q=prompt('Search messages');if(!q)return;try{const d=await api(API+'/search?q='+encodeURIComponent(q)+'&conversationId='+c.id);showSearchResults(d.results||[]);}catch(e){toast(e.message);}return;}hideSheet();try{const payload=k==='pinned'?{pinned:!c.pinned}:k==='muted'?{muted:!c.mutedUntil}:{archived:true};const d=await api(`${API}/conversations/${c.id}/settings`,{method:'PATCH',body:JSON.stringify(payload)});state.active=d.conversation;refreshInbox();if(k==='archived')setView('inbox');else renderChatHeader();}catch(e){toast(e.message);}});}
function showSearchResults(results){const body=ensure().querySelector('[data-msg-sheet-body]');body.innerHTML='<h3>Search results</h3>';if(!results.length)body.innerHTML+='<div class="fb-msg-empty">No messages found.</div>';for(const m of results){const b=document.createElement('button');b.className='fb-msg-setting';b.style.cssText='width:100%;margin:3px 0;text-align:left';b.textContent=(m.sender?.name||'')+': '+(m.body||m.type);b.onclick=()=>hideSheet();body.appendChild(b);}showSheet();}
async function markRead(){if(!state.active)return;clearTimeout(state.readTimer);state.readTimer=setTimeout(async()=>{const last=[...state.messages].reverse().find(m=>m.id&&!String(m.id).startsWith('tmp-'));if(!last)return;try{await api(`${API}/conversations/${state.active.id}/read`,{method:'POST',body:JSON.stringify({messageId:last.id})});const c=state.inbox.find(x=>x.id===state.active.id);if(c)c.unread=0;updateBadge();}catch(_error){}},180);}
