function renderTyping(){const el=ensure().querySelector('[data-msg-typing]'),active=[...state.typing.values()].some(time=>time&&Date.now()-time<1600);if(el)el.textContent=active?'Typing…':'';}
function notifyMessage(m){if(!m||String(m.senderId)===String(state.selfId)||state.open&&state.active?.id===m.conversationId)return;if(document.hidden&&'Notification'in window&&Notification.permission==='granted'){try{new Notification(m.sender?.name||'New message',{body:m.body||('Sent '+m.type),icon:m.sender?.avatar||undefined,tag:'fb-msg-'+m.conversationId});}catch(_error){}}}
async function contacts(q=''){try{const d=await api(API+'/contacts?q='+encodeURIComponent(q));state.contacts=d.contacts||[];renderContacts();}catch(e){toast(e.message);}}
function syncContactPage(){const page=ensure(),title=page.querySelector('.fb-msg-contact-toolbar h2'),group=page.querySelector('[data-msg-group-toggle]'),create=page.querySelector('[data-msg-create-group]');title.textContent=state.groupMode?'New group':'New message';group.hidden=state.groupMode;create.classList.toggle('show',state.groupMode&&state.groupSelected.size>0);create.textContent=`Create group${state.groupSelected.size?` (${state.groupSelected.size})`:''}`;}
