async function startRecording(){if(state.recording){state.recording.stop();return;}try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const rec=new MediaRecorder(stream);state.recordChunks=[];rec.ondataavailable=e=>{if(e.data.size)state.recordChunks.push(e.data);};rec.onstop=()=>{stream.getTracks().forEach(t=>t.stop());const blob=new Blob(state.recordChunks,{type:rec.mimeType||'audio/webm'});const file=new File([blob],'voice-message.webm',{type:blob.type});sendFile(file,'audio');state.recording=null;ensure().querySelector('[data-msg-mic]').classList.remove('fb-msg-recording');};rec.start(250);state.recording=rec;ensure().querySelector('[data-msg-mic]').classList.add('fb-msg-recording');}catch(_error){toast('Microphone permission is required for voice messages.');}}
function toast(text){const old=document.querySelector('.fb-msg-toast');if(old)old.remove();const t=document.createElement('div');t.className='fb-msg-toast';t.textContent=text;t.style.cssText='position:fixed;z-index:2147483647;left:50%;bottom:90px;transform:translateX(-50%);background:#1c1e21;color:#fff;padding:9px 14px;border-radius:18px;font:13px Arial;max-width:85vw;text-align:center';document.body.appendChild(t);setTimeout(()=>t.remove(),2400);}
