function addMediaPipelineStyles(){if(document.getElementById('facebookMessengerV143MediaStyle'))return;const style=document.createElement('style');style.id='facebookMessengerV143MediaStyle';style.textContent=`#facebookMessengerPage .v143-preview-status{position:absolute;z-index:3;left:50%;bottom:22px;transform:translateX(-50%);display:none;max-width:82%;border-radius:18px;background:#1c1e21dd;color:#fff;padding:8px 13px;font-size:12px;text-align:center}#facebookMessengerPage .v86-preview-item.is-converting .v143-preview-status,#facebookMessengerPage .v86-preview-item.is-unavailable .v143-preview-status{display:block}#facebookMessengerPage .v86-preview-item.v146-video-poster:after{content:'▶';position:absolute;z-index:2;left:50%;top:50%;transform:translate(-50%,-50%);width:58px;height:58px;border-radius:50%;display:grid;place-items:center;padding-left:4px;background:rgba(0,0,0,.58);color:#fff;font-size:25px}#facebookMessengerPage .v143-upload-state{display:flex;align-items:center;justify-content:flex-end;gap:8px;min-height:24px;margin-top:5px;color:#65676b;font-size:11px}#facebookMessengerPage .v143-upload-state button{border:0;border-radius:14px;background:#e4e6eb;color:#0866ff;padding:5px 11px;font-weight:700}#facebookMessengerPage .v86-upload.is-failed .v86-upload-card{opacity:1}`;document.head.appendChild(style);}
function page(){return document.getElementById('facebookMessengerPage');}
function toast(text){document.querySelector('.v86-toast')?.remove();const t=document.createElement('div');t.className='v86-toast';t.textContent=text;t.style.cssText='position:fixed;z-index:2147483647;left:50%;bottom:90px;transform:translateX(-50%);background:#1c1e21;color:#fff;padding:9px 14px;border-radius:18px;font:13px Arial';document.body.appendChild(t);setTimeout(()=>t.remove(),2400);}
async function json(url,options={}){const r=await baseFetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let d={};try{d=await r.json();}catch(_e){}if(!r.ok)throw new Error(d.error||'Something went wrong.');return d;}
