async function sendText(event){event.preventDefault();const viewer=ensure(),input=viewer.querySelector('[data-v99-input]'),body=input.value.trim(),c=conversation();if(!body||!active?.messageId||!c)return;try{await request(`${API}/conversations/${c.id}/messages`,{method:'POST',body:JSON.stringify({clientId:`photo-reply-${Date.now()}-${Math.random().toString(36).slice(2)}`,body,replyToId:active.messageId})});input.value='';syncSend();input.focus({preventScroll:true});toast('Reply sent');}catch(error){toast(error.message);}}
async function sendPhoto(file){const c=conversation();if(!file||!c||!active?.messageId)return;try{const response=await fetch(`${API}/conversations/${c.id}/attachment`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/octet-stream','X-File-Name':encodeURIComponent(file.name||'photo.jpg'),'X-File-Type':file.type||'image/jpeg','X-Client-Id':`photo-reply-${Date.now()}-${Math.random().toString(36).slice(2)}`,'X-Reply-To-Id':active.messageId},body:file}),data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Could not send photo.');toast('Photo reply sent');}catch(error){toast(error.message);}}
function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y);}function midpoint(a,b){return{x:(a.x+b.x)/2,y:(a.y+b.y)/2};}
function pointerDown(event){event.currentTarget.setPointerCapture?.(event.pointerId);pointers.set(event.pointerId,{x:event.clientX,y:event.clientY,startX:event.clientX,startY:event.clientY,time:Date.now()});moved=false;if(pointers.size===1)gesture={baseX:tx,baseY:ty,startX:event.clientX,startY:event.clientY};if(pointers.size===2&&active?.kind!=='video'){const[a,b]=[...pointers.values()];gesture={distance:distance(a,b),scale,mid:midpoint(a,b),baseX:tx,baseY:ty};pinched=true;}}
