function wire(viewer){viewer.querySelector('[data-v99-close]').onclick=close;viewer.querySelector('[data-v99-more]').onclick=event=>{event.stopPropagation();viewer.querySelector('.v99-photo-menu').classList.toggle('show');};viewer.querySelector('[data-v99-download]').onclick=download;viewer.querySelector('[data-v99-story]').onclick=addToStory;viewer.querySelector('[data-v99-input]').addEventListener('input',syncSend);viewer.querySelector('.v99-photo-reply').addEventListener('submit',sendText);viewer.querySelector('[data-v99-camera]').onclick=()=>viewer.querySelector('[data-v99-file]').click();viewer.querySelector('[data-v99-file]').onchange=event=>{sendPhoto(event.target.files[0]);event.target.value='';};viewer.addEventListener('pointerdown',event=>{if(!event.target.closest('.v99-photo-menu')&&!event.target.closest('[data-v99-more]'))viewer.querySelector('.v99-photo-menu').classList.remove('show');},true);const stage=viewer.querySelector('.v99-photo-stage');stage.addEventListener('pointerdown',pointerDown);stage.addEventListener('pointermove',pointerMove);stage.addEventListener('pointerup',pointerUp);stage.addEventListener('pointercancel',pointerUp);stage.addEventListener('wheel',wheel,{passive:false});}
