async function renderAddPeople(){setScreen('Add people','<div class="v97-add-list" data-v97-add-list><div class="v94-empty">Loading…</div></div>','add');try{const data=await request(`${API}/contacts`),ids=new Set((current().participants||[]).map(p=>String(p.id))),people=(data.contacts||[]).filter(p=>!ids.has(String(p.id)));ensure().querySelector('[data-v97-add-list]').innerHTML=people.map(p=>`<div class="v97-person" data-person="${esc(p.id)}">${avatar(p)}<span><strong>${esc(p.name)}</strong></span><button>Add</button></div>`).join('')||'<div class="v94-empty">Everyone is already in this group.</div>';ensure().querySelectorAll('[data-person] button').forEach(button=>button.onclick=async()=>{const row=button.closest('[data-person]');try{const data=await request(`${API}/conversations/${current().id}/members`,{method:'POST',body:JSON.stringify({userId:row.dataset.person})});window.__facebookMessengerApplyConversation?.(data.conversation);renderPeople();}catch(error){toast(error.message);}});}catch(error){toast(error.message);}}
