function getPage(){return document.getElementById('facebookMessengerPage');}
function syncSendState(){const p=getPage(),input=p?.querySelector('[data-msg-input]'),send=p?.querySelector('[data-msg-send]');if(!input||!send)return;const enabled=Boolean(input.value.trim());send.disabled=!enabled;send.setAttribute('aria-disabled',String(!enabled));const image=send.querySelector('img');if(image)image.src=enabled?'/icons/comment-send-enabled.png':'/icons/comment-send-disabled.png';}
function decorateActionMenu(){const p=getPage(),sheet=p?.querySelector('[data-msg-sheet]'),body=p?.querySelector('[data-msg-sheet-body]');if(!sheet||!body)return;const grid=body.querySelector('.v86-action-grid'),reactions=body.querySelector('.v86-reactions');sheet.classList.toggle('v87-message-actions',Boolean(grid&&reactions));if(!grid||!reactions)return;if(!reactions.querySelector('.v87-reaction-label'))reactions.insertAdjacentHTML('afterbegin','<span class="v87-reaction-label">Tap + to customize reactions</span>');grid.querySelectorAll('button[data-action]').forEach(button=>{if(button.dataset.v87)return;button.dataset.v87='1';const action=button.dataset.action,label=action==='delete'?'Unsend':action==='delete-me'?'Delete for me':action.charAt(0).toUpperCase()+action.slice(1);button.innerHTML=(actionIcons[action]||'')+`<span>${label}</span>`;});}
function stopTrustedBubbleTap(line){if(line.dataset.v87Tap)return;line.dataset.v87Tap='1';line.querySelector('.fb-msg-bubble')?.addEventListener('click',event=>{if(event.isTrusted&&!event.target.closest('button,a,audio,video,input,.fb-msg-reactions')){event.preventDefault();event.stopImmediatePropagation();}},true);}
function wireEmojiSwipe(){const p=getPage(),panel=p?.querySelector('[data-msg-emojis]');if(!panel||panel.dataset.v87Swipe)return;panel.dataset.v87Swipe='1';let x=0,y=0;panel.addEventListener('touchstart',event=>{const touch=event.touches[0];x=touch.clientX;y=touch.clientY;},{passive:true});panel.addEventListener('touchend',event=>{const touch=event.changedTouches[0],dx=touch.clientX-x,dy=touch.clientY-y;if(Math.abs(dx)<55||Math.abs(dx)<Math.abs(dy)*1.25)return;const tabs=[...panel.querySelectorAll('[data-cat]')],current=Math.max(0,tabs.findIndex(tab=>tab.classList.contains('on'))),next=Math.max(0,Math.min(tabs.length-1,current+(dx<0?1:-1)));if(next!==current){tabs[next].click();requestAnimationFrame(()=>panel.querySelector('[data-cat].on')?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'}));}},{passive:true});panel.querySelector('.v86-emoji-tabs')?.addEventListener('click',event=>{if(event.target.closest('[data-cat]'))setTimeout(()=>panel.querySelector('[data-cat].on')?.scrollIntoView({behavior:'smooth',inline:'center',block:'nearest'}),0);});p.querySelector('[data-msg-emoji]')?.addEventListener('click',()=>setTimeout(()=>p.querySelector('[data-msg-input]')?.blur(),0),true);}
