function sameBurst(first,second){if(!first||!second||first.classList.contains('mine')!==second.classList.contains('mine')||first.dataset.senderId!==second.dataset.senderId)return false;const a=new Date(first.dataset.createdAt),b=new Date(second.dataset.createdAt),gap=b-a;if(!Number.isFinite(gap)||gap<0||gap>BURST_MS)return false;return a.getFullYear()===b.getFullYear()&&a.getMonth()===b.getMonth()&&a.getDate()===b.getDate();}
function openProfile(userId){if(!userId||typeof window.__facebookOpenUserProfile!=='function')return;const root=page(),returnToInfo=Boolean(window.__facebookMessengerProfileReturn?.returnToInfo);window.__facebookMessengerProfileReturn={active:true,returnToInfo};try{history.pushState(Object.assign({},history.state||{},{facebookMessengerProfileReturn:true}),'',location.href);}catch(_error){}root?.querySelector('[data-msg-close]')?.click();requestAnimationFrame(()=>window.__facebookOpenUserProfile(userId));}
