function removeMyReaction(line){const messageId=line.dataset.messageId;if(!/^\d+$/.test(messageId))return;window.__facebookMessengerHoldMessagePosition?.(line);fetch('/api/messaging/messages/'+messageId+'/reaction',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({emoji:''})}).catch(()=>{});page()?.querySelector('[data-msg-sheet]')?.classList.remove('show');}
function showReactions(line,badge){const root=page(),sheet=root?.querySelector('[data-msg-sheet]'),body=root?.querySelector('[data-msg-sheet-body]'),details=Array.isArray(badge._reactionDetails)?badge._reactionDetails:[];if(!sheet||!body||!details.length)return;body.innerHTML='<h3 class="v91-reaction-title">Reactions</h3>'+details.map((reaction,index)=>{const userId=String(reaction.userId||reaction.userid||''),mine=reaction.mine===true||String(reaction.mine).toLowerCase()==='true'||Boolean(userId&&line.dataset.selfId&&userId===line.dataset.selfId),name=reaction.name||(mine?'You':'Facebook user'),avatar=reaction.avatar||(userId?'/api/users/'+encodeURIComponent(userId)+'/avatar':'');return `<button class="v91-reaction-person" data-reaction-index="${index}" data-mine="${mine?'1':'0'}">${avatar?`<img src="${escapeHtml(avatar)}" alt="">`:`<span class="v91-reaction-avatar">${escapeHtml(name.slice(0,1).toUpperCase())}</span>`}<span><strong>${escapeHtml(name)}</strong>${mine?'<small>Tap to remove</small>':''}</span><span class="v91-reaction-emoji">${escapeHtml(reaction.emoji)}</span></button>`;}).join('');sheet.classList.add('v91-reaction-sheet','show');body.querySelectorAll('[data-mine="1"]').forEach(button=>button.onclick=()=>removeMyReaction(line));}
function bindReactions(){page()?.querySelectorAll('.fb-msg-line').forEach(line=>{const badge=line.querySelector('.fb-msg-reactions');if(!badge||badge.dataset.v91Reaction)return;badge.dataset.v91Reaction='1';badge.setAttribute('role','button');badge.setAttribute('tabindex','0');const open=event=>{event.preventDefault();event.stopPropagation();showReactions(line,badge);};badge.addEventListener('click',open);badge.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' ')open(event);});});}
