function ensure(){let root=page(),details=root?.querySelector('.v94-info');if(details)return details;details=document.createElement('section');details.className='v94-info';details.innerHTML=`<header class="v94-info-head"><button data-v94-back aria-label="Back">${icon('back')}</button><h2 data-v94-title></h2><span></span></header><main class="v94-info-body" data-v94-body></main>`;root.querySelector('.fb-msg-chat').appendChild(details);details.querySelector('[data-v94-back]').onclick=()=>{if(details.dataset.view&&details.dataset.view!=='home')renderHome();else details.classList.remove('show');};return details;}
