function renderSearch(){setScreen('Search','<div class="v94-search"><input data-v94-search-input placeholder="Search in conversation" autocomplete="off"><div data-v94-results></div></div>','search');const input=ensure().querySelector('[data-v94-search-input]'),results=ensure().querySelector('[data-v94-results]');let timer,searchResults=[];input.oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const q=input.value.trim();if(!q){results.innerHTML='';return;}try{const data=await request(`${API}/search?q=${encodeURIComponent(q)}&conversationId=${encodeURIComponent(conversation().id)}`);searchResults=(data.results||[]).filter(message=>message.type!=='system');results.innerHTML=searchResults.map((message,index)=>`<button class="v94-result" data-result-index="${index}"><strong>${esc(message.sender?.name||'Facebook user')}</strong><small>${esc(message.body||message.type)}</small></button>`).join('')||'<div class="v94-empty">No messages found</div>';results.querySelectorAll('[data-result-index]').forEach(button=>button.onclick=async()=>{const message=searchResults[Number(button.dataset.resultIndex)];if(!message)return;results.innerHTML='<div class="v119-older-loader v154-search-loader" role="status" aria-label="Loading message"><i></i></div>';try{ensure().classList.remove('show');await window.__facebookMessengerOpenSearchMessage?.(message);}catch(error){toast(error.message);}});}catch(error){results.innerHTML=`<div class="v94-empty">${esc(error.message)}</div>`;}},240);};requestAnimationFrame(()=>input.focus());}
