function allEmojis(){const found=[...document.querySelectorAll('[data-msg-emojis] [data-e], [data-msg-emojis] .v88-emoji-page button')].map(button=>button.dataset.e||button.textContent.trim()).filter(Boolean);return [...new Set(found.length?found:fallbackEmojis)];}
function renderEmojiPicker(){const editor=ensure(),emojis=allEmojis();editor.className='v98-group-editor show v98-emoji-view';editor.innerHTML=`<header class="v98-editor-head"><button data-back>Cancel</button><button data-emoji-done>Done</button></header><main class="v98-editor-body"><div class="v98-emoji-preview"><span data-emoji-preview style="background:${draft.color}">${draft.emoji||'😎'}</span></div><div class="v98-color-row">${colors.map(color=>`<button data-color="${color}" style="background:${color}" class="${color===draft.color?'selected':''}"></button>`).join('')}</div><label class="v98-emoji-search">⌕<input data-search placeholder="Search"></label><div class="v98-all-emojis">${emojis.map(emoji=>`<button data-pick="${emoji}" class="${emoji===draft.emoji?'selected':''}">${emoji}</button>`).join('')}</div></main>`;let selected=draft.emoji||'😎',color=draft.color;const refresh=()=>{const preview=editor.querySelector('[data-emoji-preview]');preview.textContent=selected;preview.style.background=color;editor.querySelectorAll('[data-color]').forEach(button=>button.classList.toggle('selected',button.dataset.color===color));editor.querySelectorAll('[data-pick]').forEach(button=>button.classList.toggle('selected',button.dataset.pick===selected));};editor.querySelector('[data-back]').onclick=renderEditorKeepingDraft;editor.querySelector('[data-emoji-done]').onclick=()=>{draft.emoji=selected;draft.color=color;draft.image='';renderEditorKeepingDraft();};editor.querySelectorAll('[data-color]').forEach(button=>button.onclick=()=>{color=button.dataset.color;refresh();});editor.querySelectorAll('[data-pick]').forEach(button=>button.onclick=()=>{selected=button.dataset.pick;refresh();});editor.querySelector('[data-search]').oninput=event=>{const query=event.target.value.trim();editor.querySelectorAll('[data-pick]').forEach(button=>button.style.display=!query||button.dataset.pick.includes(query)?'':'none');};refresh();}
