function imageData(file){return new Promise((resolve,reject)=>{if(!file)return resolve('');const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{const canvas=document.createElement('canvas');canvas.width=240;canvas.height=240;const ctx=canvas.getContext('2d'),side=Math.min(image.width,image.height);ctx.drawImage(image,(image.width-side)/2,(image.height-side)/2,side,side,0,0,240,240);URL.revokeObjectURL(url);resolve(canvas.toDataURL('image/jpeg',.72));};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('Could not read this image.'));};image.src=url;});}
