function addMemberEditButton(){const hero=page()?.querySelector('.v97-group-info.show .v97-group-hero');if(!hero||hero.querySelector('[data-v97-edit]'))return;const button=document.createElement('button');button.dataset.v97Edit='';button.textContent='Change name and image';hero.appendChild(button);}
function init(){addStyles();const root=page();if(!root)return setTimeout(init,30);ensure();window.__facebookMessengerEditGroup=renderEditor;const list=root.querySelector('[data-msg-inbox]'),info=root.querySelector('.v97-group-info');new MutationObserver(fixInbox).observe(list,{childList:true,subtree:true});if(info){new MutationObserver(addMemberEditButton).observe(info,{childList:true,subtree:true});info.addEventListener('click',event=>{const button=event.target.closest('[data-v97-edit]');if(!button)return;event.preventDefault();event.stopImmediatePropagation();renderEditor();},true);}fixInbox();}
document.addEventListener('click',event=>{if(!event.target.closest?.('.v98-group-editor [data-more]'))return;draft.name=ensure().querySelector('[data-name]')?.value||conversation()?.name||'';},true);
